FILE: app/src/walkthrough.ts
```ts
import type { FreeCamera, SceneContext } from "@babylonjs/lite";
import { createFreeCamera, attachFreeControl } from "@babylonjs/lite";

type Vec = { x: number; y: number; z: number };

export interface Walkthrough {
  readonly camera: FreeCamera;
  jumpTo(eye: Vec, target: Vec): void;
  dispose(): void;
}

export function createWalkthrough(
  canvas: HTMLCanvasElement,
  scene: SceneContext,
  eye: Vec,
  target: Vec,
): Walkthrough {
  const camera = createFreeCamera(eye, target);
  scene.camera = camera;
  const disposeControl = attachFreeControl(camera, canvas, scene);

  function jumpTo(eye: Vec, target: Vec): void {
    camera.position.x = eye.x;
    camera.position.y = eye.y;
    camera.position.z = eye.z;
    camera.target.x = target.x;
    camera.target.y = target.y;
    camera.target.z = target.z;

    const dx = target.x - eye.x;
    const dy = target.y - eye.y;
    const dz = target.z - eye.z;
    camera._yaw = Math.atan2(dx, dz);
    camera._pitch = Math.atan2(dy, Math.sqrt(dx * dx + dz * dz));
  }

  function dispose(): void {
    disposeControl();
  }

  return { camera, jumpTo, dispose };
}
```

I created `src/walkthrough.ts` which builds a free camera at the given eye/target, attaches the standard free-control to the canvas (giving the usual WASD/arrows + drag-to-look behaviour), and exposes `jumpTo` that repositions the camera and syncs the internal `_yaw`/`_pitch` so the controls carry on from the new orientation, plus `dispose` which calls the disposer returned by `attachFreeControl` to remove all canvas listeners and the per-frame hook. I was not entirely sure whether `scene.camera` is a settable property on `SceneContext` (its full declaration wasn't in the provided files), but the requirement states the camera should be `scene.camera`, so I assign it directly.
